import{_ as d,o as r,c as a,a4 as e}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"BNSF铁路","description":"","frontmatter":{"title":"BNSF铁路"},"headers":[],"relativePath":"03_companies/BNSF铁路.md","filePath":"03_companies/BNSF铁路.md"}'),l={name:"03_companies/BNSF铁路.md"};function o(h,t,i,n,s,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="bnsf铁路" tabindex="-1">BNSF铁路 <a class="header-anchor" href="#bnsf铁路" aria-label="Permalink to &quot;BNSF铁路&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>首次提及</strong></td><td>2009年</td></tr><tr><td><strong>收购公告</strong></td><td>2009年11月2日宣布</td></tr><tr><td><strong>收购完成</strong></td><td>2010年2月12日正式完成</td></tr><tr><td><strong>收购总成本</strong></td><td>约440亿美元（含承担约100亿美元债务，实际现金加股票支付约340亿美元）</td></tr><tr><td><strong>持股比例</strong></td><td>伯克希尔哈撒韦100%持有</td></tr><tr><td><strong>行业</strong></td><td>铁路货运运输（一级铁路）</td></tr><tr><td><strong>英文名</strong></td><td>BNSF Railway (Burlington Northern Santa Fe)</td></tr><tr><td><strong>总部</strong></td><td>沃斯堡，得克萨斯州</td></tr><tr><td><strong>前身公司</strong></td><td>伯灵顿北方铁路（Burlington Northern）+ 圣菲铁路（Santa Fe）于1995年合并</td></tr><tr><td><strong>铁路历史</strong></td><td>可追溯至1850年，最早前身线路为伊利诺伊州东北部一条12英里线路</td></tr><tr><td><strong>合并记录</strong></td><td>拥有390条前身躯干铁路的收购与合并记录</td></tr><tr><td><strong>运营网络</strong></td><td>覆盖28个州，23,759英里主轨道</td></tr><tr><td><strong>基础设施</strong></td><td>13,495座桥梁、99条隧道、7,521台机车</td></tr><tr><td><strong>员工人数</strong></td><td>约47,000人</td></tr><tr><td><strong>年货运量</strong></td><td>约7亿吨英里（2014年数据）</td></tr><tr><td><strong>列车里程</strong></td><td>1.43亿英里/年（2021年数据）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>BNSF是美国最大的铁路货运公司，按货运量（吨英里）计，是北美六大一级铁路系统中规模最大的。公司主要运输以下大宗商品：</p><ul><li><strong>工业产品</strong>：化工产品、塑料、钢铁</li><li><strong>农产品</strong>：谷物、化肥、种子</li><li><strong>能源</strong>：煤炭（面临长期下降趋势）、石油（2012年每日约运输50万桶，约占低48州总产量的10%）</li><li><strong>消费品</strong>：日用品、零售商品</li><li><strong>汽车</strong>：整车及零部件</li></ul><h3 id="运营效率优势" tabindex="-1">运营效率优势 <a class="header-anchor" href="#运营效率优势" aria-label="Permalink to &quot;运营效率优势&quot;">​</a></h3><p>BNSF以卓越的燃油效率著称：一加仑柴油可将一吨货物运输约500英里，是卡车燃油效率的约四倍。按每吨英里收入计算，BNSF收费约3美分，比其他四家主要美国铁路低40%以上（其他铁路为4.2至5.3美分）。这一成本优势使BNSF成为美国经济循环系统中最重要的动脉。</p><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="无可复制的网络效应" tabindex="-1">无可复制的网络效应 <a class="header-anchor" href="#无可复制的网络效应" aria-label="Permalink to &quot;无可复制的网络效应&quot;">​</a></h3><p>巴菲特在2023年股东信中指出：&quot;BNSF是覆盖北美的六大铁路系统中最大的一个。我们的铁路在其资产负债表上以700亿美元记录了23,759英里的主线、99条隧道、13,495座桥梁、7,521台机车和各种其他固定资产。但我的猜测是，复制这些资产至少需要5000亿美元，而且需要数十年才能完成。&quot;</p><h3 id="高资本壁垒" tabindex="-1">高资本壁垒 <a class="header-anchor" href="#高资本壁垒" aria-label="Permalink to &quot;高资本壁垒&quot;">​</a></h3><p>铁路运输是典型的&quot;户外运动&quot;：长达一英里的列车必须在极寒和极热中可靠运行，同时穿越从沙漠到山区的各种地形，大规模洪水定期发生。这种极端运营环境形成了极高的进入壁垒。</p><h3 id="利息保障能力强" tabindex="-1">利息保障能力强 <a class="header-anchor" href="#利息保障能力强" aria-label="Permalink to &quot;利息保障能力强&quot;">​</a></h3><p>即使在经济衰退年份，BNSF的利息覆盖率仍保持健康水平：</p><ul><li>2010年（大衰退期间）：利息覆盖率6:1</li><li>2011年（经济疲弱）：利息覆盖率9.5:1</li><li>2012年（经济疲弱）：利息覆盖率9.6:1</li><li>2014年（不景气年份）：利息覆盖率超过8:1</li><li>2015年（不景气年份）：利息覆盖率超过8:1</li><li>2016年（令人失望的年份）：利息覆盖率超过6:1</li></ul><h3 id="强大的自由现金流能力" tabindex="-1">强大的自由现金流能力 <a class="header-anchor" href="#强大的自由现金流能力" aria-label="Permalink to &quot;强大的自由现金流能力&quot;">​</a></h3><p>BNSF每年必须花费超过其折旧费用以维持业务水平，但长期来看，其充足的现金流使其能够自主融资扩张，无需伯克希尔哈撒韦提供债务担保。</p><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;2009年末，在大衰退的阴霾中，我们同意收购BNSF铁路——伯克希尔哈撒韦历史上最大的一笔收购。当时，我称这笔交易为&#39;对美国经济未来的全押注&#39;。&quot; ——2013年、2014年股东信</p></blockquote><blockquote><p>&quot;收购BNSF后，我们拥有了约25.7万名员工、数百个独立经营单元，未来还会继续增加。但我们绝不允许伯克希尔哈撒韦变成被委员会、预算报告、多层管理压垮的庞然大物，而是将其作为一批独立管理的大中型企业集合，多数决策在经营层面完成。&quot; ——2009年股东信</p></blockquote><blockquote><p>&quot;铁路运输美国42%的城际货运（按吨英里计算），而BNSF运输的铁路货运量超过任何其他铁路——约占行业总量的28%。简单的数学告诉你，美国超过11%的城际货运吨英里是由BNSF运输的。&quot; ——2010年股东信</p></blockquote><blockquote><p>&quot;BNSF按吨英里计算，运送了所有城际货运的约15%（无论通过卡车、铁路、水运、空运还是管道运输）。确实，我们运输的货物吨英里数比任何人都多，这使BNSF成为我们经济循环系统中最重要的大动脉。&quot; ——2012年股东信</p></blockquote><blockquote><p>&quot;BNSF像所有铁路一样，也以极其节油和环境友好的方式运输货物——使用一加仑柴油可将一吨货物运输约500英里。做同样工作的卡车大约要多消耗四倍的燃料。&quot; ——2013年股东信</p></blockquote><blockquote><p>&quot;查理和我热爱我们的铁路，这是我们最好的收购之一。&quot; ——2016年股东信</p></blockquote><blockquote><p>&quot;铁路对美国的经济未来至关重要。从成本、燃料使用和碳强度来看，它显然是将重型货物运往远方最有效的方式。卡车在短途运输中胜出，但美国人需要的许多货物必须运往数百甚至数千英里外的客户。没有铁路，这个国家无法运转，而且该行业的资本需求始终巨大。&quot; ——2023年股东信</p></blockquote><blockquote><p>&quot;BNSF每年必须花费超过其折旧费用，以维持其目前的业务水平。这一现实对所有者不利，无论他们投资于哪个行业，但在资本密集型行业中尤其不利。&quot; ——2023年股东信</p></blockquote><blockquote><p>&quot;在这里，我要冒昧做一个罕见的预言：BNSF铁路将在一个世纪后依然是伯克希尔哈撒韦和我们国家的关键资产。&quot; ——2021年股东信</p></blockquote><blockquote><p>&quot;BNSF铁路，我们的第三大巨头，继续是美国商业的第一大动脉，这使其成为美国以及伯克希尔哈撒韦不可或缺的资产。如果BNSF运输的许多重要产品改为卡车运输，美国的碳排放量将大幅飙升。&quot; ——2021年股东信</p></blockquote><blockquote><p>&quot;您的铁路公司在2021年实现了创纪录的60亿美元收益。&quot; ——2021年股东信</p></blockquote><blockquote><p>&quot;去年（2023年），我对我们两个最大业务BNSF铁路和BHE的预期是错误的。&quot; ——2023年股东信</p></blockquote><blockquote><p>&quot;伯克希尔哈撒韦的铁路和公用事业业务——我们保险业务之外的两大业务——其综合收益有所改善。然而，两者都还有很多工作要做。&quot; ——2024年股东信</p></blockquote><blockquote><p>&quot;在BNSF，2024年是充满挑战的一年。尽管运营业绩有所改善，但盈利从2023年的约51亿美元下降至约50亿美元。如果剔除2023年因税法调整产生的一次性税收优惠（约4亿美元），实际降幅更大。好消息是：我们的许多运营指标在2024年最后一个季度有了显著改善。我们预计2025年将取得实质性进展。&quot; ——2024年股东信（巴菲特原文综合表述）</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><h3 id="年度净利润-伯克希尔哈撒韦视角" tabindex="-1">年度净利润（伯克希尔哈撒韦视角） <a class="header-anchor" href="#年度净利润-伯克希尔哈撒韦视角" aria-label="Permalink to &quot;年度净利润（伯克希尔哈撒韦视角）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>BNSF净利润（百万美元）</th><th>备注</th></tr></thead><tbody><tr><td>2010</td><td>约2,459</td><td>2010年2月12日起并表（部分年度）</td></tr><tr><td>2011</td><td>约2,972</td><td>全资持有首年</td></tr><tr><td>2012</td><td>约3,372</td><td>创纪录年份之一</td></tr><tr><td>2013</td><td>约3,793</td><td>创纪录年份之一</td></tr><tr><td>2014</td><td>约3,869</td><td></td></tr><tr><td>2015</td><td>约4,248</td><td>创纪录年份之一</td></tr><tr><td>2016</td><td>约6,685</td><td>创纪录年份</td></tr><tr><td>2017</td><td>—</td><td>贡献约44%的非保险税前利润（约88亿美元税前）</td></tr><tr><td>2018</td><td>—</td><td>税前盈利93亿美元（与BHE合计）</td></tr><tr><td>2019</td><td>—</td><td>与BHE合计盈利83亿美元</td></tr><tr><td>2020</td><td>—</td><td>疫情期间在艰难年份持续盈利</td></tr><tr><td>2021</td><td><strong>约60亿（创纪录）</strong></td><td>巴菲特原文：&quot;创纪录的60亿美元&quot;</td></tr><tr><td>2022</td><td><strong>约59亿</strong></td><td>巴菲特原文：&quot;盈利59亿美元&quot;</td></tr><tr><td>2023</td><td><strong>约50.87亿</strong></td><td>低于预期</td></tr><tr><td>2024</td><td><strong>约50.31亿</strong></td><td>充满挑战的一年</td></tr></tbody></table><h3 id="关键财务指标" tabindex="-1">关键财务指标 <a class="header-anchor" href="#关键财务指标" aria-label="Permalink to &quot;关键财务指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数据</th></tr></thead><tbody><tr><td>固定资产账面价值</td><td>700亿美元</td></tr><tr><td>复制成本估算</td><td>5,000亿美元以上（巴菲特估算）</td></tr><tr><td>利息覆盖率</td><td>6:1至9.6:1（历年）</td></tr><tr><td>每吨英里收费</td><td>约3美分（低于行业40%以上）</td></tr><tr><td>燃油效率</td><td>每加仑柴油运输约500英里/吨</td></tr><tr><td>折旧费用（2016年）</td><td>21亿美元（ GAAP口径，实际维护支出远超此数）</td></tr><tr><td>2013年资本支出</td><td>40亿美元（折旧费的2倍）</td></tr><tr><td>2014年资本支出</td><td>60亿美元（约占收入的26%）</td></tr><tr><td>2015年资本支出</td><td>60亿美元</td></tr><tr><td>自收购以来累计资本支出</td><td>超过410亿美元（截至2020年）</td></tr><tr><td>累计支付股息</td><td>超过418亿美元（截至2020年）</td></tr></tbody></table><h3 id="_2016年详细财务数据" tabindex="-1">2016年详细财务数据 <a class="header-anchor" href="#_2016年详细财务数据" aria-label="Permalink to &quot;2016年详细财务数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>金额</th></tr></thead><tbody><tr><td>收入</td><td>198.29亿美元</td></tr><tr><td>营业费用</td><td>131.44亿美元</td></tr><tr><td>利息和税前经营利润</td><td>约66.85亿美元</td></tr><tr><td>利息（净额）</td><td>—</td></tr><tr><td>所得税</td><td>—</td></tr><tr><td>净利润</td><td>约66.85亿美元</td></tr></tbody></table><h3 id="bnsf与bhe合计盈利" tabindex="-1">BNSF与BHE合计盈利 <a class="header-anchor" href="#bnsf与bhe合计盈利" aria-label="Permalink to &quot;BNSF与BHE合计盈利&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>合计盈利</th></tr></thead><tbody><tr><td>2011</td><td>约42亿美元</td></tr><tr><td>2017</td><td>约93亿美元</td></tr><tr><td>2018</td><td>约93亿美元</td></tr><tr><td>2019</td><td>约83亿美元</td></tr><tr><td>2020</td><td>约83亿美元（艰难年份）</td></tr><tr><td>占伯克希尔税后经营收益比例</td><td>约30%-37%</td></tr></tbody></table><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><strong>马特·罗斯（Matt Rose）</strong>：BNSF时任CEO，2009年与巴菲特会面后促成收购，收购后继续担任CEO多年</li><li><strong>卡尔·艾斯（Carl Ice）</strong>：BNSF CEO，2020年按计划退休</li><li><strong>凯蒂·法默（Katie Farmer）</strong>：2020年底接任卡尔·艾斯成为BNSF CEO</li><li><strong>格雷格·阿贝尔（Greg Abel）</strong>：伯克希尔哈撒韦副董事长，主管BHE（中美能源），与BNSF并列为伯克希尔两大资本密集型业务负责人</li><li><strong>阿吉特·贾恩（Ajit Jain）</strong>：伯克希尔保险业务负责人，与BNSF共同构成伯克希尔四大珍宝</li></ul><h2 id="伯克希尔哈撒韦四大珍宝" tabindex="-1">伯克希尔哈撒韦四大珍宝 <a class="header-anchor" href="#伯克希尔哈撒韦四大珍宝" aria-label="Permalink to &quot;伯克希尔哈撒韦四大珍宝&quot;">​</a></h2><p>巴菲特将BNSF列为伯克希尔四大珍宝企业之一（2019-2020年表述）：</p><ol><li><strong>伯克希尔哈撒韦保险业务</strong>（核心业务，53年来从未改变）</li><li><strong>BNSF铁路</strong>（100%持有）</li><li><strong>苹果公司</strong>（持股约5.4%）</li><li><strong>伯克希尔哈撒韦能源（BHE）</strong>（持股约91%-92%）</li></ol><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1850、1995、1996、2009、2010、2011、2012、2013、2014、2015、2016、2017、2018、2019、2020、2021、2022、2023、2024</p><p>（注：1850年为BNSF最早前身线路开始运营的年份。1995年为伯灵顿北方与圣菲合并成立BNSF的年份。）</p><h2 id="重要时间线" tabindex="-1">重要时间线 <a class="header-anchor" href="#重要时间线" aria-label="Permalink to &quot;重要时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>事件</th></tr></thead><tbody><tr><td>1850年</td><td>BNSF最早前身线路（伊利诺伊州12英里线路）开始运营</td></tr><tr><td>1995年</td><td>伯灵顿北方铁路与圣菲铁路合并，成立BNSF Railway</td></tr><tr><td>1996年</td><td>BNSF首个完整运营年度：货运周转量4.11亿吨英里，员工45,000人</td></tr><tr><td>2009年10月22日</td><td>巴菲特在沃斯堡与BNSF CEO马特·罗斯首次会面</td></tr><tr><td>2009年11月2日</td><td>伯克希尔哈撒韦宣布收购BNSF，每股100美元，总价约440亿美元</td></tr><tr><td>2010年2月12日</td><td>收购正式完成，BNSF成为伯克希尔全资子公司</td></tr><tr><td>2011年</td><td>BNSF全资运营首年，税前利润47.41亿美元，净利润29.72亿美元</td></tr><tr><td>2012年</td><td>BNSF每日运输约50万桶石油，约占低48州总产量的10%</td></tr><tr><td>2013年</td><td>资本支出40亿美元，为折旧费的2倍，创任何铁路单年纪录</td></tr><tr><td>2014年</td><td>资本支出60亿美元（占收入的26%）；因服务问题导致部分客户流失</td></tr><tr><td>2015年</td><td>继续投入60亿美元改善运营</td></tr><tr><td>2016年</td><td>净利润约66.85亿美元，创纪录年份</td></tr><tr><td>2017年</td><td>贡献约44%的非保险税前利润</td></tr><tr><td>2019年</td><td>与BHE合计盈利83亿美元</td></tr><tr><td>2020年</td><td>CEO卡尔·艾斯按计划退休，凯蒂·法默接任</td></tr><tr><td>2021年</td><td>创纪录的60亿美元收益；列车行驶1.43亿英里，运输5.35亿吨货物</td></tr><tr><td>2022年</td><td>盈利59亿美元</td></tr><tr><td>2023年</td><td>盈利50.87亿美元，低于年初预期</td></tr><tr><td>2024年</td><td>盈利50.31亿美元；运营指标在年末显著改善</td></tr><tr><td>2025年</td><td>预计将取得实质性进展</td></tr></tbody></table><h2 id="运营亮点与挑战" tabindex="-1">运营亮点与挑战 <a class="header-anchor" href="#运营亮点与挑战" aria-label="Permalink to &quot;运营亮点与挑战&quot;">​</a></h2><h3 id="亮点" tabindex="-1">亮点 <a class="header-anchor" href="#亮点" aria-label="Permalink to &quot;亮点&quot;">​</a></h3><ul><li>2021年创纪录：列车行驶1.43亿英里，运输5.35亿吨货物，远超任何其他美国运输公司</li><li>2014年安全记录改善：1996年可报告工伤率为每20万人时2.04起，此后下降超过50%至0.95</li><li>2013年资本支出40亿美元，为折旧费的两倍，创任何铁路单年纪录</li><li>煤炭运输面临长期下降，但石油等新兴货运品类弥补了部分缺口</li></ul><h3 id="挑战" tabindex="-1">挑战 <a class="header-anchor" href="#挑战" aria-label="Permalink to &quot;挑战&quot;">​</a></h3><ul><li><strong>2014年服务问题</strong>：铁路让许多客户失望，失去市场份额给联合太平洋铁路</li><li><strong>煤炭量下降</strong>：与其他铁路一起，未来十年将失去大量煤炭运量（2015年信中提及）</li><li><strong>资本密集</strong>：每年必须花费超过折旧费用以维持业务，对股东不利</li><li><strong>折旧费用不足</strong>：铁路记录的折旧费用远低于维持一流运营状态所需的实际支出，导致GAAP盈利高于真实经济盈利</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/search.html?q=2009年股东信">2009年股东信</a></li><li><a href="/search.html?q=2010年股东信">2010年股东信</a></li><li><a href="/search.html?q=2011年股东信">2011年股东信</a></li><li><a href="/search.html?q=2012年股东信">2012年股东信</a></li><li><a href="/search.html?q=2013年股东信">2013年股东信</a></li><li><a href="/search.html?q=2014年股东信">2014年股东信</a></li><li><a href="/search.html?q=2015年股东信">2015年股东信</a></li><li><a href="/search.html?q=2016年股东信">2016年股东信</a></li><li><a href="/search.html?q=2017年股东信">2017年股东信</a></li><li><a href="/search.html?q=2018年股东信">2018年股东信</a></li><li><a href="/search.html?q=2019年股东信">2019年股东信</a></li><li><a href="/search.html?q=2020年股东信">2020年股东信</a></li><li><a href="/search.html?q=2021年股东信">2021年股东信</a></li><li><a href="/search.html?q=2022年股东信">2022年股东信</a></li><li><a href="/search.html?q=2023年股东信">2023年股东信</a></li><li><a href="/search.html?q=2024年股东信">2024年股东信</a></li><li><a href="/search.html?q=2025年股东信">2025年股东信</a></li><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a></li><li><a href="/search.html?q=伯克希尔哈撒韦能源">伯克希尔哈撒韦能源</a></li><li><a href="/search.html?q=马特·罗斯">马特·罗斯</a></li><li><a href="/04_people/格雷格·阿贝尔.html">格雷格·阿贝尔</a></li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/2009年/翻译.html">/01_letters/2009年/翻译</a></li><li><a href="/01_letters/2010年/翻译.html">/01_letters/2010年/翻译</a></li><li><a href="/01_letters/翻译.html">/01_letters//翻译</a></li><li><a href="/01_letters/翻译.html">/01_letters//翻译</a></li></ul>',62)])])}const c=d(l,[["render",o]]);export{b as __pageData,c as default};
